            atype = data.get('@type', 'NO TYPE')
            if atype != 'Article':
                errors.append(f"{fname}: @type = {atype}")
        except json.JSONDecodeError as e:
            errors.append(f"{fname}: JSON parse error - {e}")

if errors:
    print(f"JSON-LD issues found ({len(errors)}):")
    for e in errors:
        print(f"  {e}")
else:
    print("All 59 files: JSON-LD Article schemas are VALID JSON ✅")
