import os, re, glob

BLOG = "/root/.hermes/workspace/chinahospitalsguide/blog"
BASE_URL = "https://chinahospitalsguide.com"
files = sorted(glob.glob(f"{BLOG}/*.html"))
files = [f for f in files if not f.endswith("index.html")]

issues = []
for fpath in files:
    fname = os.path.basename(fpath)
    name = fname.replace(".html", "")
    content = open(fpath, encoding='utf-8').read()
    expected = f"{BASE_URL}/blog/{name}.html"

    canonicals = re.findall(r'<link rel="canonical" href="[^"]*"', content)
    og_urls = re.findall(r'<meta property="og:url" content="[^"]*"', content)
    tw_cards = re.findall(r'<meta name="twitter:card"', content)
    og_site = re.findall(r'<meta property="og:site_name"', content)
    has_article = bool(re.search(r'"@type"\s*:\s*"Article"', content))

    problems = []
    if len(canonicals) != 1: problems.append(f"canonical:{len(canonicals)}")
    elif expected not in canonicals[0]: problems.append(f"canonical:wrong")
    if len(og_urls) != 1: problems.append(f"og_url:{len(og_urls)}")
    if len(tw_cards) != 1: problems.append(f"twitter:{len(tw_cards)}")
    if len(og_site) != 1: problems.append(f"og_site:{len(og_site)}")
    if not has_article: problems.append("no_article")

    if problems:
        issues.append((fname, problems))

if issues:
    print(f"ISSUES ({len(issues)} files):")
    for fname, probs in issues:
        print(f"  {fname}: {', '.join(probs)}")
else:
    print(f"ALL {len(files)} PASS - clean canonical/og:url/twitter/og_site/article")
"}

